INSERT INTO title (name_fa, name_en, release_date, age_rating, summary, t_type, duration_mins) VALUES
('تلقین', 'Inception', '2010-07-16', 'PG-13', 'دزدی که اسرار شرکتی را از طریق فناوری اشتراک‌گذاری رویا می‌دزدد، مأموریت معکوسی به او داده می‌شود: کاشتن یک ایده در ذهن یک مدیرعامل.', 'M', 148),
('شوالیه تاریکی', 'The Dark Knight', '2008-07-18', 'PG-13', 'بتمن با بزرگترین تهدید خود، جوکر، روبرو می‌شود که گاتهام را به هرج و مرج می‌کشاند.', 'M', 152),
('داستان عامه‌پسند', 'Pulp Fiction', '1994-10-14', 'R', 'زندگی دو قاتل حرفه‌ای، یک بوکسور، یک گانگستر و همسرش در چهار داستان از خشونت و رستگاری به هم گره می‌خورد.', 'M', 154),
('فارست گامپ', 'Forrest Gump', '1994-07-06', 'PG-13', 'تاریخ ایالات متحده از دهه ۱۹۵۰ تا ۱۹۷۰ از چشم‌انداز مردی از آلاباما با ضریب هوشی ۷۵ روایت می‌شود.', 'M', 142),
('ماتریکس', 'The Matrix', '1999-03-31', 'R', 'یک هکر کامپیوتر از شورشیان مرموز درباره ماهیت واقعی واقعیت خود و نقشش در جنگ علیه کنترل‌کنندگان آن می‌آموزد.', 'M', 136),
('تایتانیک', 'Titanic', '1997-12-19', 'PG-13', 'یک اشراف‌زاده هفده ساله عاشق یک هنرمند مهربان اما فقیر در کشتی لوکس و بدشانس تایتانیک می‌شود.', 'M', 194),
('گلادیاتور', 'Gladiator', '2000-05-05', 'R', 'یک ژنرال سابق رومی به دنبال انتقام از امپراتور فاسدی است که خانواده‌اش را به قتل رساند و او را به بردگی فرستاد.', 'M', 155),
('انگل', 'Parasite', '2019-05-30', 'R', 'یک خانواده فقیر نقشه می‌کشند تا توسط یک خانواده ثروتمند استخدام شده و به خانه آنها نفوذ کنند.', 'M', 132),
('اوپنهایمر', 'Oppenheimer', '2023-07-21', 'R', 'داستان دانشمند آمریکایی جی. رابرت اوپنهایمر و نقش او در توسعه بمب اتمی.', 'M', 180),
('شبکه اجتماعی', 'The Social Network', '2010-10-01', 'PG-13', 'داستان تأسیس فیس‌بوک و دعاوی حقوقی که به دنبال آن آمد.', 'M', 120);
INSERT INTO title (name_fa, name_en, release_date, age_rating, summary, t_type, duration_mins) VALUES
('بازی تاج و تخت', 'Game of Thrones', '2011-04-17', 'TV-MA', 'هفت پادشاهی وستروس درگیر جنگی برای تصاحب تخت آهنین هستند در حالی که یک تهدید باستانی از شمال در حال بازگشت است.', 'S', NULL),
('بریکینگ بد', 'Breaking Bad', '2008-01-20', 'TV-MA', 'یک معلم شیمی مبتلا به سرطان ریه برای تأمین آینده خانواده‌اش شروع به تولید و فروش متامفتامین می‌کند.', 'S', NULL),
('چیزهای عجیب', 'Stranger Things', '2016-07-15', 'TV-14', 'ناپدید شدن پسری در شهر کوچک هاوکینز، رازهای فراطبیعی و یک دختر با قدرت‌های روانی را فاش می‌کند.', 'S', NULL),
('تاج', 'The Crown', '2016-11-04', 'TV-MA', 'زندگی و سلطنت ملکه الیزابت دوم از ازدواجش در ۱۹۴۷ تا دوران مدرن.', 'S', NULL),
('جانشینی', 'Succession', '2018-06-03', 'TV-MA', 'خانواده روی، صاحبان یک امپراتوری رسانه‌ای جهانی، برای آینده شرکت پس از بازنشستگی پدرسالار سالخورده خود رقابت می‌کنند.', 'S', NULL),
('دارک', 'Dark', '2017-12-01', 'TV-MA', 'ناپدید شدن دو کودک در یک شهر آلمانی، چهار خانواده را در یک معمای زمانی پیچیده درگیر می‌کند.', 'S', NULL),
('وست‌ورلد', 'Westworld', '2016-10-02', 'TV-MA', 'در پارکی تفریحی با ربات‌های شبیه انسان، مهمانان می‌توانند هر آرزویی را برآورده کنند، اما ربات‌ها شروع به بیدار شدن می‌کنند.', 'S', NULL),
('مندلورین', 'The Mandalorian', '2019-11-12', 'TV-14', 'یک شکارچی جایزه‌بگیر تنها در لبه‌های کهکشان، سفری را با یک کودک مرموز آغاز می‌کند.', 'S', NULL),
('هاوس آو د دراگون', 'House of the Dragon', '2022-08-21', 'TV-MA', 'دویست سال پیش از بازی تاج و تخت، خاندان تارگرین درگیر جنگ داخلی بر سر جانشینی می‌شوند.', 'S', NULL),
('آخرین بازمانده از ما', 'The Last of Us', '2023-01-15', 'TV-MA', 'در یک جهان پساآخرالزمانی، یک قاچاقچی و یک نوجوان مصون از عفونت، سفری خطرناک را آغاز می‌کنند.', 'S', NULL);